from pathlib import Path
p=Path('index.html'); s=p.read_text(encoding='utf-8')
nav_css='''<style id="mcl-seo-nav-css">.mcl-seo-nav{display:flex;align-items:center;gap:9px;margin-left:auto;margin-right:14px;font:800 11px "Space Mono",sans-serif}.mcl-seo-nav a{padding:9px 11px;border:1px solid var(--line);border-radius:999px;background:#fffefa;color:var(--ink);transition:.18s ease}.mcl-seo-nav a:hover{background:var(--olive-bright);transform:translateY(-1px)}@media(max-width:900px){.mcl-seo-nav{display:none}}</style>'''
if '<nav class="mcl-seo-nav"' not in s:
 s=s.replace('</style>\n</head>',nav_css+'\n</style>\n</head>',1)
 nav='<nav class="mcl-seo-nav" aria-label="Murder Crow learning navigation"><a href="/about/">About</a><a href="/blog/">Learn</a><a href="/blog/">Blog</a></nav>'
 s=s.replace(' <button class="navcta" onclick="openReservation()">Join Lab →</button>',' '+nav+' <button class="navcta" onclick="openReservation()">Join Lab →</button>',1)
hub=r'''<style id="mcl-learn-hub-css">.mcl-learn-hub{position:relative;overflow:hidden}.mcl-learn-hub .mcl-hub-head{display:flex;justify-content:space-between;align-items:end;gap:25px;margin-bottom:25px}.mcl-learn-hub h2{font:800 clamp(38px,5.5vw,68px)/.94 Manrope;letter-spacing:-.065em;max-width:800px}.mcl-learn-hub h2 em{font-style:normal;color:var(--olive)}.mcl-learn-hub .mcl-hub-copy{max-width:430px;color:var(--muted);font-size:15px}.mcl-learn-grid{display:grid;grid-template-columns:1.2fr .8fr .8fr;gap:13px}.mcl-learn-card{border:1px solid var(--line);border-radius:25px;background:var(--paper2);padding:27px;min-height:210px;display:flex;flex-direction:column;justify-content:space-between;position:relative;overflow:hidden}.mcl-learn-card:after{content:"";position:absolute;left:-20%;right:-20%;top:23%;height:1px;background:linear-gradient(90deg,transparent,rgba(104,119,43,.35),transparent);transform:rotate(-4deg);animation:mclHubLine 6s linear infinite}.mcl-learn-card.dark{background:var(--ink);color:#fff;border-color:var(--ink)}.mcl-learn-card.lime{background:var(--olive-bright);border-color:var(--ink)}.mcl-learn-card h3{font:800 25px/1.02 Manrope;letter-spacing:-.045em;margin:8px 0}.mcl-learn-card p{font-size:12px;color:var(--muted);max-width:420px}.mcl-learn-card.dark p{color:#d4d8cf}.mcl-learn-card.lime p{color:#30350f}.mcl-learn-kicker{font:700 9px "Space Mono";letter-spacing:.15em;color:var(--olive)}.mcl-learn-card.dark .mcl-learn-kicker{color:var(--olive-bright)}.mcl-learn-card.lime .mcl-learn-kicker{color:var(--ink)}.mcl-learn-link{display:inline-flex;align-items:center;gap:6px;font-weight:900;font-size:11px;color:var(--olive);position:relative;z-index:2}.mcl-learn-card.dark .mcl-learn-link{color:var(--olive-bright)}@keyframes mclHubLine{0%{transform:translateX(-20%) rotate(-4deg)}100%{transform:translateX(20%) rotate(-4deg)}}@media(max-width:800px){.mcl-learn-hub .mcl-hub-head{display:block}.mcl-learn-hub .mcl-hub-copy{margin-top:12px}.mcl-learn-grid{grid-template-columns:1fr}.mcl-learn-card{min-height:170px;padding:23px}.mcl-learn-hub{padding-top:52px;padding-bottom:52px}}</style><section class="mcl-learn-hub section reveal" id="murder-crow-learn"><div class="wrap"><div class="mcl-hub-head"><div><div class="kicker">08 · MURDER CROW LEARN</div><h2>Learn digital marketing.<br><em>Understand how growth works.</em></h2></div><p class="mcl-hub-copy">Simple, practical guides for people searching for digital marketing, digital marketing courses, AI tools, how AI tools work, social media marketing, SEO, growth marketing and marketing careers.</p></div><div class="mcl-learn-grid"><article class="mcl-learn-card dark"><div><div class="mcl-learn-kicker">MURDER CROW LEARN</div><h3>Start with digital marketing.</h3><p>SEO, social media, ads, content, analytics, funnels, AI and growth — explained without making beginners feel lost.</p></div><a class="mcl-learn-link" href="/blog/">Explore the Learn library →</a></article><article class="mcl-learn-card lime"><div><div class="mcl-learn-kicker">AI TOOLS</div><h3>How do AI tools work?</h3><p>Understand what AI tools actually do and where they fit into real marketing work.</p></div><a class="mcl-learn-link" href="/blog/how-ai-tools-work.html">Read the guide →</a></article><article class="mcl-learn-card"><div><div class="mcl-learn-kicker">THE STORY</div><h3>Why Murder Crow?</h3><p>A murder is a group of crows. We made it our idea for a collective of creative people who learn, build, experiment and help each other grow.</p></div><a class="mcl-learn-link" href="/about/">About Murder Crow →</a></article></div></div></section>'''
if 'id="murder-crow-learn"' not in s: s=s.replace('</main>',hub+'</main>',1)
footer_css='''<style id="mcl-footer-links-css">.mcl-footer-links{display:flex;flex-wrap:wrap;gap:8px 16px;margin-top:20px;padding-top:18px;border-top:1px solid #30332b}.mcl-footer-links a{font:700 10px "Space Mono",sans-serif;color:#c7cbc0;letter-spacing:.04em}.mcl-footer-links a:hover{color:var(--olive-bright)}@media(max-width:620px){.mcl-footer-links{gap:12px}.mcl-footer-links a{font-size:9px}}</style>'''
footer_links='''<div class="mcl-footer-links" aria-label="Footer navigation"><a href="/about/">About Murder Crow</a><a href="/blog/">Blog / Learn</a><a href="#ask-crow">Support</a><a href="/terms-and-conditions.html">Terms &amp; Conditions</a></div>'''
if 'id="mcl-footer-links-css"' not in s:
 s=s.replace('</style>\n</head>',footer_css+'\n</style>\n</head>',1)
if 'class="mcl-footer-links"' not in s and '</div></footer>' in s:
 s=s.replace('</div></footer>',footer_links+'</div></footer>',1)
if '<meta name="author" content="Murder Crow Labs">' not in s: s=s.replace('<meta name="description"','<meta name="author" content="Murder Crow Labs">\n<meta name="description"',1)

# Global mobile/three-line menu: About, Services, Skill Up, Learn, Support.
if 'href="/menu.css"' not in s:
    s=s.replace('</head>','<link rel="stylesheet" href="/menu.css">\n</head>',1)
if 'src="/menu.js"' not in s:
    s=s.replace('</head>','<script defer src="/menu.js"></script>\n</head>',1)

p.write_text(s,encoding='utf-8')
